#!/usr/bin/env python3
"""Scoped private S03/CP55 backup under existing maintenance lock; no resume/delete.
Only categorical results cross the existing owner-maintenance public log boundary.
"""
import sys
sys.dont_write_bytecode = True
import base64, fcntl, hashlib, json, os, re, selectors, signal, shutil, sqlite3, stat, subprocess, time, types
from pathlib import Path
ROOT = Path('/root/nox')
STATE = ROOT / 'state'
OUTPUT = ROOT / 'lora/qwen35_9b/6907283384'
CHECKPOINT = 'checkpoint-u00000055-a00000055-g01794833901774705882'
MANIFEST_SHA = '458310555dc0a2a5e4e7b3fa127e7a642bb1d5651aa2393777c50f0c6c4e1a65'
PROFILES = (STATE / 'cold_drive.conf', Path('/root/.config/rclone/rclone.conf'), ROOT / 'rclone.conf')
FLAGS = (ROOT / 'STOP', STATE / 'OWNER_MAINTENANCE.flag', STATE / 'TRAIN_HOLD.flag', STATE / 'TRAIN_PAUSE_REQUEST.flag')
HELPER_SHA = '957b8dce05e7c0c9439bb52f9f8af98a46ce939b8d441f306438b273f601118d'
HELPER_B64 = ''
PAYLOAD_SHA = {'README.md': '737e3df079d72e8e52cb3b0b9a5a22e5dcec2a0b51e1bf97fbb5cc1f310ebaa2', 'adapter_config.json': 'c75a7a638e83a417c3b7c421898a9338acc0f90f1c4d62155034ebd10059d7af', 'adapter_model.safetensors': '7969b80d2b9909bcaad50984904c8e83ed0563560d06c7c4f1e6e707b1d616e8', 'lineage.json': '19345f9992a8a4a0537c9b9f84ffb086164e1c898eb0207c53569469645f3cb0', 'optimizer.pt': '94807af108a97210c97280bce06d86ac4ad4aa4e89a0273a796bb0de56707646', 'python_rng.json': '6c1f7cf78612e65f70f7a963bd3f439eeecfacb362f4634bd4737d7e1eddd292', 'rng_state.pt': '41ab9806d56bbaea53567f18abce55dcd283228f5a8cde9778209b779476bddc', 'scaler.pt': 'db8f0b608f7ff901407e7d87d867046142d258cffcd768734737a63f381286ca', 'scheduler.pt': '2d16dd7d402e127a4670c00fd419dfb6f1c35a9a9828b1c219cb13c28614fa77', 'student_state.json': 'ca349563443f14cf02e6333cf7a593bf59b68a20ba1160e5388edb130f3fb2f8'}
MAX_FILE = 1024 ** 3
MAX_TOTAL = 2 * 1024 ** 3
RESERVE = 6 * 1024 ** 3
DEADLINE = None
SAFE_PATH = '/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin'

def executable(name):
    value = shutil.which(name, path=SAFE_PATH)
    require(value is not None, 'EXECUTABLE_UNAVAILABLE')
    return value

class Hold(RuntimeError): pass

def require(ok, reason):
    if not ok: raise Hold('HOLD_PRIVATE_BACKUP_' + reason)

def remaining(maximum=60):
    left = DEADLINE - time.monotonic() if DEADLINE else maximum
    require(left > 0, 'DEADLINE')
    return max(0.1, min(maximum, left))

def plain(path):
    path = Path(path)
    require(path.is_absolute(), 'PATH')
    require(not any(p.is_symlink() for p in (*path.parents, path)), 'SYMLINK')
    return path

def identity(info):
    return (info.st_dev, info.st_ino, info.st_size, info.st_mtime_ns, info.st_ctime_ns)

def read_regular(path, maximum=262144):
    path = plain(path)
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
    try:
        before = os.fstat(fd)
        require(stat.S_ISREG(before.st_mode) and before.st_uid == os.geteuid()
                and not before.st_mode & 0o022 and before.st_size <= maximum, 'FILE_SCOPE')
        data = os.read(fd, maximum + 1)
        require(len(data) == before.st_size and identity(before) == identity(os.fstat(fd))
                == identity(path.lstat()), 'FILE_CHANGED')
        return data
    finally: os.close(fd)

def fixed_hash(path): return hashlib.sha256(read_regular(path, 1048576)).hexdigest()

def flag_snapshot():
    for p in FLAGS[:2]: require(p.is_file(), 'OWNER_STOP_REQUIRED')
    return {str(p): fixed_hash(p) if p.exists() else None for p in FLAGS}

def run(argv, maximum=30):
    # Never return stderr: providers may include credentials or signed URLs.
    result = subprocess.run(argv, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,
                            stderr=subprocess.DEVNULL, timeout=remaining(maximum),
                            env={**os.environ, 'LC_ALL':'C'})
    require(len(result.stdout) <= 262144, 'OUTPUT_LIMIT')
    require(result.returncode in (0, 3), 'COMMAND_EXIT')
    return result.returncode, result.stdout

def stopped_services():
    rc, raw = run([executable('supervisorctl'), 'status'], 15)
    rows = [l.split() for l in raw.decode('utf-8','replace').splitlines() if l.startswith('nox-')]
    require(bool(rows) and all(len(x) >= 2 and x[1] in ('STOPPED','EXITED','FATAL') for x in rows), 'SERVICES_NOT_STOPPED')
    return len(rows)

def profile_probe():
    candidates = []
    for p in PROFILES:
        row = {'present':p.exists(), 'private_metadata':False, 'nox_drive_available':False}
        candidates.append(row)
        if not p.exists(): continue
        try:
            plain(p); info = p.lstat()
            row['private_metadata'] = stat.S_ISREG(info.st_mode) and info.st_uid == os.geteuid() and stat.S_IMODE(info.st_mode) == 0o600
            if not row['private_metadata']: continue
            rc, raw = run([executable('rclone'),'--config',str(p),'listremotes'], 15)
            row['nox_drive_available'] = rc == 0 and b'nox_drive:' in raw.splitlines()
            if row['nox_drive_available']: return p, candidates
        except (OSError, Hold, subprocess.TimeoutExpired):
            row['probe_failed'] = True
    return None, candidates

def helper_module():
    raw = base64.b64decode(HELPER_B64, validate=True)
    require(hashlib.sha256(raw).hexdigest() == HELPER_SHA, 'HELPER_PIN')
    module = types.ModuleType('_nox_pc_export_reused')
    exec(compile(raw, '<pinned-nox-pc-export>', 'exec'), module.__dict__)
    return module

def checkpoint_rows(helper):
    directory = plain(OUTPUT / CHECKPOINT)
    manifest = read_regular(directory / 'checkpoint_manifest.json')
    require(hashlib.sha256(manifest).hexdigest() == MANIFEST_SHA, 'CP55_MANIFEST_PIN')
    result = []
    for name, expected in PAYLOAD_SHA.items():
        path = plain(directory / name)
        info = path.lstat()
        require(stat.S_ISREG(info.st_mode) and info.st_uid == os.geteuid() and 0 <= info.st_size <= MAX_FILE, 'CP55_FILE_SCOPE')
        before = identity(info)
        require(helper.sha256(path) == expected and identity(path.lstat()) == before, 'CP55_PAYLOAD_SHA')
        result.append((path, 'checkpoint55/' + name, expected))
    result.append((directory/'checkpoint_manifest.json','checkpoint55/checkpoint_manifest.json',MANIFEST_SHA))
    return result

def warm_inventory():
    # Metadata only. We do not pretend this preserves the warm weight bytes.
    names = ('merged_hf','models','progress_pull_t784u')
    count = total = 0
    for name in names:
        root = ROOT / name
        if not root.exists(): continue
        plain(root)
        visited = 0
        for folder, dirs, files in os.walk(root, followlinks=False):
            visited += 1
            require(visited <= 2000, 'WARM_INVENTORY_BOUND')
            dirs[:] = [d for d in dirs if not (Path(folder)/d).is_symlink() and d not in ('credentials','secrets','.git')]
            for name in files:
                p = Path(folder)/name
                if p.suffix.lower() not in ('.safetensors','.gguf','.pt','.bin','.pth') or p.is_symlink(): continue
                info = p.lstat()
                if stat.S_ISREG(info.st_mode): count += 1; total += info.st_size
                require(count <= 2000, 'WARM_INVENTORY_BOUND')
    return {'files':count, 'bytes':total, 'content_hashed':False, 'transferred':False}

def copy_stream_restore(profile, remote, destination, size, expected):
    destination = plain(destination)
    destination.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
    fd = os.open(destination, os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW, 0o600)
    proc = None
    digest, count = hashlib.sha256(), 0
    try:
        proc = subprocess.Popen([executable('rclone'),'--config',str(profile),'cat',remote,
                                 '--retries','1','--low-level-retries','1','--contimeout','10s','--timeout','30s'],
                                stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
        with os.fdopen(fd,'wb') as out:
            fd = None
            with selectors.DefaultSelector() as selector:
                selector.register(proc.stdout, selectors.EVENT_READ)
                while selector.get_map():
                    for key, _ in selector.select(remaining(1)):
                        block = os.read(key.fd, 1024*1024)
                        if not block: selector.unregister(key.fileobj); continue
                        count += len(block)
                        require(count <= size, 'REMOTE_OVERSIZE')
                        digest.update(block); out.write(block)
                require(proc.wait(timeout=remaining(5)) == 0, 'REMOTE_EXIT')
            require(count == size and digest.hexdigest() == expected, 'REMOTE_RESTORE_SHA')
            out.flush(); os.fsync(out.fileno())
    finally:
        if fd is not None: os.close(fd)
        if proc is not None:
            if proc.poll() is None: proc.kill()
            proc.wait(timeout=5)
            if proc.stdout: proc.stdout.close()
    return count

def transfer(profile, source, remote, restore, helper):
    before = identity(source.stat()); digest = helper.sha256(source)
    args = [executable('rclone'),'--config',str(profile),'copyto',str(source),remote,
            '--immutable','--transfers','1','--checkers','1','--multi-thread-streams','1',
            '--retries','1','--low-level-retries','1','--contimeout','10s','--timeout','30s']
    rc, _ = run(args, 180)
    require(rc == 0, 'UPLOAD_FAILED')
    count = copy_stream_restore(profile, remote, restore, before[2], digest)
    require(identity(source.stat()) == before and helper.sha256(restore) == digest, 'SOURCE_OR_RESTORE_CHANGED')
    return {'bytes':count,'sha256':digest}

def execute():
    global DEADLINE
    DEADLINE = time.monotonic() + 810
    request = os.environ.get('NOX_OWNER_REQUEST_ID','')
    source = os.environ.get('NOX_OWNER_SOURCE_SHA','')
    require(bool(re.fullmatch(r'[0-9]{1,24}', request)) and bool(re.fullmatch(r'[a-f0-9]{40}', source)), 'OWNER_CONTEXT')
    before_flags = flag_snapshot()
    services = stopped_services()
    profile, probes = profile_probe()
    metadata = {'schema':'NOX_PRIVATE_BACKUP_V1','task_ids':['2V14-04','2V14-07'],
                'instance':60509551,'source_sha':source,'request':request,'profiles':probes,
                'stopped_services':services,'source_deleted':False,'resume_attempted':False,
                'private_contents_exported_to_logs':False,'snapshots_written':False,
                'warm_weights_transferred':False,'functional_training_restore_verified':False}
    if profile is None:
        require(flag_snapshot() == before_flags, 'FLAGS_CHANGED')
        return {**metadata,'state':'HOLD_NO_EXISTING_PRIVATE_NOX_DRIVE_PROFILE','source_writes':0,'uploaded_bytes':0}
    lock_path = plain(STATE/'owner_maintenance.lock')
    lock = os.open(lock_path,os.O_CREAT|os.O_RDWR|os.O_NOFOLLOW,0o600)
    try:
        require(stat.S_ISREG(os.fstat(lock).st_mode) and os.fstat(lock).st_uid == os.geteuid(), 'LEASE_FILE')
        try: fcntl.flock(lock, fcntl.LOCK_EX|fcntl.LOCK_NB)
        except BlockingIOError: raise Hold('HOLD_PRIVATE_BACKUP_WRITER_BUSY') from None
        require(flag_snapshot() == before_flags, 'FLAGS_CHANGED')
        stopped_services()
        helper = helper_module()
        rows = checkpoint_rows(helper)
        s03 = plain(ROOT/'kb/knowledge.sqlite')
        info = s03.stat()
        require(stat.S_ISREG(info.st_mode) and 0 < info.st_size < MAX_FILE, 'S03_SCOPE')
        total = info.st_size + sum(p.stat().st_size for p, _, _ in rows)
        require(total <= MAX_TOTAL, 'TOTAL_BOUND')
        fs = os.statvfs(STATE)
        require(fs.f_bavail*fs.f_frsize >= total*2 + RESERVE, 'RESERVE_6GIB')
        warm = warm_inventory()
        parent = plain(STATE/'owner_private_backups'); parent.mkdir(mode=0o700,exist_ok=True)
        stage = plain(parent/('NOX49-'+request)); stage.mkdir(mode=0o700)
        snapshot = stage/'snapshots'; snapshot.mkdir(mode=0o700)
        restored = stage/'isolated_restore'; restored.mkdir(mode=0o700)
        helper.snapshot_sqlite(s03, snapshot/'s03.sqlite')
        metadata['snapshots_written'] = True
        items = [(snapshot/'s03.sqlite','s03.sqlite',None)]
        for p, relative, expected in rows:
            dst = snapshot/relative
            helper.copy_snapshot(p,dst)
            require(helper.sha256(dst) == expected, 'SNAPSHOT_PIN')
            items.append((dst,relative,expected))
        remote_root = 'nox_drive:NOX_PRIVATE_BACKUPS/NOX49-'+request
        receipts = []
        for p, relative, _ in items:
            remaining(); require(flag_snapshot() == before_flags, 'FLAGS_CHANGED')
            row = transfer(profile,p,remote_root+'/'+relative,restored/relative,helper)
            receipts.append({'relative':relative,**row})
        with sqlite3.connect((restored/'s03.sqlite').as_uri()+'?mode=ro',uri=True) as db:
            require(db.execute('PRAGMA quick_check').fetchall()==[('ok',)], 'S03_RESTORE_QUICKCHECK')
        require(flag_snapshot()==before_flags, 'FLAGS_CHANGED')
        stopped_services()
        receipt = {**metadata,'state':'PRIVATE_CP55_S03_BYTE_RESTORE_VERIFIED','files':receipts,
                   'warm_inventory':warm,'uploaded_bytes':sum(x['bytes'] for x in receipts),
                   'sqlite_restore_verified':True,'checkpoint_byte_restore_verified':True,
                   'full_2V14_04_acceptance':False,'full_2V14_07_acceptance':False}
        helper.atomic_json(stage/'receipt.json',receipt)
        transfer(profile,stage/'receipt.json',remote_root+'/receipt.json',restored/'receipt.json',helper)
        # Public stdout contains counts and booleans only, never file contents.
        return {k:v for k,v in receipt.items() if k != 'files'}
    finally: os.close(lock)

def main():
    try:
        result = execute()
        print('NOX_MAINT_DEPLOY='+json.dumps(result,separators=(',',':')),flush=True)
        print('NOX_MAINT_DEPLOY_COMPLETE=true',flush=True)
        return 0
    except Exception as exc:
        reason = str(exc)
        if not re.fullmatch(r'HOLD_[A-Z0-9_]+',reason): reason='HOLD_PRIVATE_BACKUP_'+type(exc).__name__.upper()
        print('NOX_MAINT_DEPLOY='+json.dumps({'state':reason,'accepted_ids':[],
              'source_deleted':False,'resume_attempted':False,'private_contents_exported_to_logs':False}),flush=True)
        return 2

if __name__ == '__main__': raise SystemExit(main())
